function Get-TaskForgeStatistics {
    param([AllowEmptyCollection()][object[]]$Tasks = @())

    $items = @($Tasks)
    $total = $items.Count
    $completed = @($items | Where-Object { [string]$_.status -eq 'completed' }).Count
    $pending = @($items | Where-Object { [string]$_.status -eq 'pending' }).Count

    if ($total -eq 0) {
        $percentage = [double]0.0
    }
    else {
        $percentage = [double][math]::Round(($completed / $total) * 100, 1)
    }

    $invariant = [System.Globalization.CultureInfo]::InvariantCulture
    $counts = @{}
    foreach ($task in $items) {
        $parsed = [DateTimeOffset]::Parse(
            [string]$task.createdAt,
            $invariant,
            [System.Globalization.DateTimeStyles]::RoundtripKind)
        $date = $parsed.UtcDateTime.ToString('yyyy-MM-dd', $invariant)
        if ($counts.ContainsKey($date)) {
            $counts[$date] = [int]$counts[$date] + 1
        }
        else {
            $counts[$date] = 1
        }
    }

    $byDate = @(
        $counts.GetEnumerator() |
            Sort-Object -Property Key |
            ForEach-Object { [pscustomobject]@{ date = [string]$_.Key; count = [int]$_.Value } }
    )

    return [pscustomobject]@{
        total = [int]$total
        pending = [int]$pending
        completed = [int]$completed
        completionPercentage = [double]$percentage
        byDate = $byDate
    }
}

